    var pair=MonthlyScenarioTestSupport.create(null).calculate(Map.of(r,operation.readByIds("HOUSEHOLD",Set.of(id)).get(id)),new BigDecimal("120000")).get(id);
    assertThat(pair.financialPrice()).isEqualByComparingTo("10");assertThat(pair.customerPrice()).isEqualByComparingTo("20");

