  @Test void undatedLegacyCustomerBandsStayWithinTheFirstAdoptionDayAfterSourcesDisappear() {
    String code=code(),month="2029-03";long financeBatch=publication("HOUSEHOLD",month,"210");var row=legacy(code,"HOUSEHOLD",month,false,"S1");
    jdbc.update("INSERT INTO lp_price_range_item(supplier_code,supplier_name,material_code,material_name,spec_model,unit,range_low,lower_inclusive,range_high,upper_inclusive,range_basis,factor_rule_id,factor_code,price_excl_tax,tax_included,effective_from,business_unit_type,created_at,updated_at) VALUES('S1','S1',?,'future band','SPEC','件',100,0,200,1,'FACTOR',?,'CU',999,0,?,'HOUSEHOLD',NOW(),NOW())",code,row.getId(),YearMonth.parse(month).atDay(24));
    var r=request(code,"HOUSEHOLD",month,"210","1");var c=context("HOUSEHOLD",month,"210");var candidates=operation.resolveCandidates(c,Set.of(r));assertThat(candidates.problems()).isEmpty();
    var adopted=operation.adopt(c,plan(r,candidates.values().get(r).selection())).plan();long id=adopted.selections().get(r).monthlyPriceId();
    assertThat(adopted.selections().get(r).fact().price()).isEqualByComparingTo("10");
    jdbc.update("DELETE FROM lp_price_range_item WHERE factor_rule_id=?",row.getId());jdbc.update("DELETE FROM lp_price_range_factor_rule WHERE id=?",row.getId());
    jdbc.update("DELETE FROM lp_factor_row_ref WHERE factor_upload_batch_id=?",financeBatch);jdbc.update("DELETE FROM lp_factor_monthly_price WHERE source_upload_batch_id=?",financeBatch);jdbc.update("DELETE FROM lp_factor_upload_batch WHERE id=?",financeBatch);
    var projection=MonthlyScenarioTestSupport.create(null);
    assertThatThrownBy(()->projection.calculate(adopted.selections(),new BigDecimal("120000"))).hasMessageContaining("first-adoption date");
    String firstUseJson=jdbc.queryForObject("SELECT first_use_json FROM lp_material_monthly_price WHERE id=?",String.class,id);
    var firstUse=codec.decode(firstUseJson,MonthlyMaterialPriceService.FirstUse.class);
    assertThat(firstUse.origin().priceAsOfTime().toLocalDate()).isEqualTo(YearMonth.parse(month).atDay(23));
    var pair=projection.calculate(adopted.selections(),new BigDecimal("120000"),Map.of(id,firstUse.origin().priceAsOfTime().toLocalDate())).get(id);
    assertThat(pair.financialPrice()).isEqualByComparingTo("10");assertThat(pair.customerPrice()).isEqualByComparingTo("20");
  }

